mapper.select:
select `id`,`name`,`sort`, `is_active` as isActive from `deploy_blue_green`


        and `name` LIKE CONCAT('%', #{keyword}, '%')


limit #{startNum}, #{pageSize}

select a.`app_system_id` as appSystemId, a.`app_module_id` as appModuleId, a.`env_id` as envId, a.`resource_id`
as resourceId, a.`blue_green_id` as blueGreenId,b.`name` as blueGreenName,b.`sort` as blueGreenSort
from `deploy_app_instance_blue_green` a
join `deploy_blue_green` b on a.`blue_green_id` = b.`id` and b.`is_active` = 1
where a.`app_system_id` = #{appSystemId}
and a.`app_module_id` = #{appModuleId}
and a.`env_id` = #{envId}
and a.`resource_id` in

    #{resourceId}
